const cardStyles=[
  {id:'note',label:'Paper note'}, {id:'lined',label:'Lined journal'},
  {id:'ticket',label:'Ticket'}, {id:'tag',label:'Paper tag'},
  {id:'postcard',label:'Postcard'}, {id:'clipped',label:'Clipped note'},
  {id:'index',label:'Index card'}, {id:'photo',label:'Photo frame'}
] as const;
function weekStyleOffset(weekStart:string){const day=Math.floor(Date.parse(`${weekStart}T12:00:00Z`)/86_400_000);return Math.floor((day+4)/7)*3;}
function automaticCardStyleIndex(day:string,weekStart:string){return (dateFor(day).getDay()+weekStyleOffset(weekStart))%cardStyles.length;}
function automaticTiltIndex(day:string,weekStart:string){return (dateFor(day).getDay()+weekStyleOffset(weekStart))%7;}
function format(day: string) { return dateFor(day).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}); }
function adjacentDay(day: string, offset: -1|1) { const date=dateFor(day); date.setDate(date.getDate()+offset); return localDay(date); }
