  const moveMemory=()=>void run(async()=>{await call('journal.updateEntry',{id:entry.id,day:moveToDay,body:entry.body,timezone:entry.timezone,allowsAI:entry.allowsAI,expectedRevision:entry.revision});moved(moveToDay);});
