      {!future&&!photoHeadline&&<div className="day-copy"><h3>{!copy&&applyingSummary&&(!pageEditing||layoutPreview)&&!pageFields[`day.${date}.title`]&&!visiblePhotoCount?summaryLoading():editText(`day.${date}.title`,copy?.title||(visiblePhotoCount?localCopy.title:count?'A saved moment':'Nothing saved yet'),'Day headline')}</h3>{!hideWeeklySubheading&&((copy?.detail||(pageEditing&&!layoutPreview)||pageFields[`day.${date}.detail`]!==undefined)&&<p>{editText(`day.${date}.detail`,copy?.detail??'','Day subheading',true)}</p>)}{!hideWeeklySubheading&&!copy&&!applyingSummary&&(!pageEditing||layoutPreview)&&pageFields[`day.${date}.detail`]===undefined&&<p>{editText(`day.${date}.detail`,count?'A photo, recording or story kept here.':'A quiet day is still part of the story.','Day subheading',true)}</p>}{count>0&&<span className="kept-tag"><Icon name={first?'text':'image'} size={14}/>{count} {count===1?'memory':'memories'} kept</span>}</div>}
      <span className="day-weather-sticker" role="note" aria-label={weatherHidden?'Weather hidden. High and low temperatures unavailable.':`Weather ${weatherType}. Low ${weatherLow} degrees Fahrenheit; high ${weatherHigh} degrees Fahrenheit.`}><Icon name={weatherIconName(weatherHidden?null:weatherData?.code)} size={14}/><span className="day-weather-copy"><strong>{weatherType}</strong><span className="day-weather-range"><span>Low {weatherLow}{weatherLow==='—'?'':'°'}</span><span>High {weatherHigh}{weatherHigh==='—'?'':'°F'}</span></span></span></span>
