  async function openSummarySource(source:SummarySource){
    if(pageEditing){setPageEditNotice('Save or cancel page edits before opening a source.');return;}
    setPendingSource(source);
    if(source.kind==='summary_guidance'){if(page!=='settings')await navigate('settings');}
    else if(page!=='day'||day!==source.day)await navigate('day',source.day);
  }
  useEffect(()=>{
    if(!pendingSource)return;
    if(pendingSource.kind==='summary_guidance'){if(page!=='settings')return;}else if(page!=='day'||day!==pendingSource.day||!ready)return;
    const source=pendingSource;
    let id='';let fallback='source-originals';
    if(source.kind==='reported_text')id='source-entry-'+encodeURIComponent(source.id);
    else if(source.kind==='recognized_speech'||source.kind==='user_media')id='source-media-'+encodeURIComponent(source.id.replace(/:(speech|visual)$/,''));
    else if(source.kind==='uncertain_visual'||source.kind==='photo_inventory'){fallback='source-photos';if(source.targetID)id='source-photo-'+encodeURIComponent(source.targetID);}
    else if(source.kind==='calendar_plan'){fallback='source-calendar';const prefix=source.day+':plan:';if(source.id.startsWith(prefix))id='source-event-'+encodeURIComponent(source.id.slice(prefix.length));}
    else if(source.kind==='selected_city_weather')fallback='source-weather';
    else if(source.kind==='journal_context')fallback='source-context';
    else if(source.kind==='summary_guidance')fallback='source-guidance';
    const started=Date.now();
    const timer=window.setInterval(()=>{
      const target=(id?document.getElementById(id):null)??(Date.now()-started>=1600||!id?document.getElementById(fallback):null);
      if(!target&&Date.now()-started<3000)return;
      clearInterval(timer);
      if(target){target.scrollIntoView({block:'center',behavior:'auto'});target.focus({preventScroll:true});target.classList.add('summary-source-highlight');window.setTimeout(()=>target.classList.remove('summary-source-highlight'),3500);}
      setPendingSource(null);
    },100);
    return()=>clearInterval(timer);
  },[pendingSource,page,day,ready,entries,mediaAssets,dayEvents,dayPhotos]);
  function highlight(){
    const automatic=generated?.week??(applyingSummary?undefined:featured);
    const override=weeklyOverrideWeek===weekKey?weeklyOverride:null;
    const copy=override??automatic;
    return <article className="weekly-highlight"><span className="paperclip" aria-hidden="true"/><div className="weekly-summary-topline"><span className="highlight-label"><Icon name="sparkles" size={15}/>{editText('week.summaryLabel','WEEKLY SUMMARY','Weekly summary label')}</span></div>
      <h2>{!copy&&applyingSummary&&!pageEditing&&pageFields['week.summaryTitle']===undefined?summaryLoading():editText('week.summaryTitle',copy?.title??'Your week is still gathering.','Weekly summary headline')}</h2>
      {(copy||pageEditing||pageFields['week.summaryDetail']!==undefined)?<blockquote>{editText('week.summaryDetail',copy?.detail??'','Weekly summary',true)}</blockquote>:applyingSummary?<p className="summary-loading-space" aria-hidden="true"/>:<p>Small stories, passing thoughts, a day you want to keep. There is room for all of it.</p>}
      {!override&&summaryJob?.state==='running'&&!pageEditing&&<small role="status">{summaryNotice}</small>}
      {!pageEditing&&pageText.weekOf===weekKey&&weeklyOverrideWeek===weekKey&&!override&&pageFields['week.summaryTitle']===undefined&&pageFields['week.summaryDetail']===undefined&&summaryJob?.state==='complete'&&summaryJob.week&&<SummarySources key={summaryJob.id+':week'} id={summaryJob.id} scope="week" expected={summaryJob.week.sourceIDs.length} onOpen={source=>void openSummarySource(source)}/>}
    </article>;
  }

